function maxKSubarrays(A, k){
  const n = A.length; const pre = new Array(n+1).fill(0);
  for(let i=1;i<=n;i++) pre[i] = pre[i-1]+A[i-1];
  const neg inf = -1e18;
  let dp = Array.from({length:n+1}, ()=> new Array(k+1).fill(neg_inf));
  let best = new Array(k+1).fill(neg_inf);
  dp[0][0] = 0;
  for(let t=1;t<=k;t++) best[t] = neg_inf;
  for(let i=1;i<=n;i++){
    for(let t=1;t<=k;t++){
      best[t] = Math.max(best[t], dp[i-1][t-1] - pre[i-1]);
      dp[i][t] = Math.max(dp[i-1][t], pre[i] + best[t]);
    }
  }
  // reconstruction omitted for brevity
  return dp[n][k];
}
```

